import { useRef, useEffect } from 'react';

type Props = { value: string; onChange: (v: string) => void; placeholder?: string };

export default function {{component_name}}({ value, onChange, placeholder }: Props) {
  const ref = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    el.style.height = 'auto';
    el.style.height = el.scrollHeight + 'px';
  }, [value]);

  return (
    <textarea
      ref={ref}
      value={value}
      onChange={(e) => onChange(e.target.value)}
      placeholder={placeholder}
      rows={1}
      className="w-full px-3 py-2 border rounded resize-none overflow-hidden"
    />
  );
}
